 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # The color-2 horizontal bar separates two regions. Connect the matching
    # columns of the same-colored marks above and below it with color 4.
    divider = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if divider is None:
        return out
    top_rows = [r for r in range(divider) if any(grid[r])]
    bottom_rows = [r for r in range(divider + 1, len(grid)) if any(grid[r])]
    if not top_rows or not bottom_rows:
        return out
    top_color = next((v for v in grid[top_rows[0]] if v != 0), None)
    bottom_color = next((v for r in bottom_rows for v in grid[r] if v != 0), None)
    if top_color is None or bottom_color != top_color:
        return out
    top_cols = {c for r in top_rows for c, v in enumerate(grid[r]) if v == top_color}
    bottom_cols = {c for r in bottom_rows for c, v in enumerate(grid[r]) if v == bottom_color}
    for c in top_cols & bottom_cols:
        for r in range(top_rows[0] + 1, divider):
            if out[r][c] == 0:
                out[r][c] = 4
    return out
